def M(mid: str, rule: str, f, old, new, tests: list[str]):
    """One mutant: (id, rule, [(file, old, new), ...], tests). `f` is a file name, or a list of (file, old, new)."""
    edits = f if isinstance(f, list) else [(f, old, new)]
    return (mid, rule, edits, tests)


